// Grab all incoming items from the HTTP Request node
const items = $input.all();

// The actual payload is inside the 'json' property of the first item
const data = items[0].json;
const products = data.products;

// Helper function to calculate time remaining in total minutes
const getMinutesRemaining = (closeTimeIso) => {
  const closeTime = new Date(closeTimeIso);
  const now = new Date(); 
  const diffMs = closeTime - now;

  // If the auction is already closed, return 0
  if (diffMs <= 0) return 0;

  // Convert milliseconds to total minutes
  return Math.floor(diffMs / (1000 * 60));
};

// Map over the products to pull out the stats
const stats = products.map(product => {
  return {
    Item: product.title,
    Location: product.location.name,
    Bids: product.bidCount,
    CurrentPrice: `$${product.currentPrice}`,
    RetailPrice: `$${product.retailPrice}`,
    TimeLeftMinutes: getMinutesRemaining(product.closeTime.value), // Now outputs a pure number
    Condition: product.grade.conditionType.description
  };
});

// Sort by highest current price
stats.sort((a, b) => 
  parseFloat(b.CurrentPrice.slice(1)) - parseFloat(a.CurrentPrice.slice(1))
);

// Return the array directly.
return stats;

